	public static function brand_color() { $color = sanitize_hex_color( get_option( self::BRAND_COLOR_OPTION, self::BRAND_COLOR_DEFAULT ) ); return $color ?: self::BRAND_COLOR_DEFAULT; }
	public static function content_width() { $value = absint( get_option( self::CONTENT_WIDTH_OPTION, self::CONTENT_WIDTH_DEFAULT ) ); return in_array( $value, array( 960, 1200, 1320 ), true ) ? $value : self::CONTENT_WIDTH_DEFAULT; }
	public static function logo_url() { $id = absint( get_option( self::LOGO_ID_OPTION, 0 ) ); return $id ? (string) wp_get_attachment_image_url( $id, 'thumbnail' ) : ''; }
	public static function frontend_css_vars( $color = '' ) {
		$color = sanitize_hex_color( $color ?: self::brand_color() ) ?: self::brand_color(); $tokens = self::design_tokens(); $font = array( 'system' => 'system-ui,sans-serif', 'serif' => 'Georgia,serif', 'mono' => 'ui-monospace,monospace' )[ $tokens['font'] ]; $button_bg = 'outline' === $tokens['button'] ? 'transparent' : $color; $button_text = 'outline' === $tokens['button'] ? $color : '#fff'; $logo = self::logo_url();
