	public static function currency() { $currency = strtoupper( sanitize_text_field( get_option( self::CURRENCY_OPTION, self::CURRENCY_DEFAULT ) ) ); return preg_match( '/^[A-Z]{3}$/', $currency ) ? $currency : self::CURRENCY_DEFAULT; }
	public static function business_name() { $name = sanitize_text_field( get_option( self::BUSINESS_NAME_OPTION, get_bloginfo( 'name' ) ) ); return $name ?: get_bloginfo( 'name' ); }
	public static function support_email() { $email = sanitize_email( get_option( self::SUPPORT_EMAIL_OPTION, get_option( 'admin_email' ) ) ); return is_email( $email ) ? $email : get_option( 'admin_email' ); }
	public static function plan_change_timing() { $value = sanitize_key( get_option( self::PLAN_CHANGE_OPTION, 'period_end' ) ); return in_array( $value, array( 'immediate', 'period_end' ), true ) ? $value : 'period_end'; }
