	public static function pause_days() { return max( 0, min( 365, absint( get_option( self::PAUSE_DAYS_OPTION, 0 ) ) ) ); }
	public static function renewal_reminder_days() { return max( 0, min( 30, absint( get_option( self::RENEWAL_REMINDER_DAYS_OPTION, 0 ) ) ) ); }
	public static function offer_reminder_days() { return min( 30, max( 0, absint( get_option( self::OFFER_REMINDER_DAYS_OPTION, 0 ) ) ) ); }
	public static function retry_max_attempts() { return max( 1, min( 10, absint( get_option( self::RETRY_MAX_ATTEMPTS_OPTION, 3 ) ?: 3 ) ) ); }
	public static function retry_backoff_minutes() { return max( 5, min( 1440, absint( get_option( self::RETRY_BACKOFF_MINUTES_OPTION, 15 ) ?: 15 ) ) ); }
	public static function abandoned_retention_days() { return max( 1, min( 90, absint( get_option( self::ABANDONED_RETENTION_DAYS_OPTION, 7 ) ?: 7 ) ) ); }
	public static function pending_activation_retention_days() { return max( 1, min( 90, absint( get_option( self::PENDING_ACTIVATION_RETENTION_DAYS_OPTION, 7 ) ?: 7 ) ) ); }
	public static function account_deletion_retention_days() { return max( 1, min( 365, absint( get_option( self::ACCOUNT_DELETION_RETENTION_DAYS_OPTION, 30 ) ?: 30 ) ) ); }
	public static function require_second_admin() { return (bool) get_option( self::SECOND_ADMIN_OPTION, false ); }
	public static function can_manage() { return ( function_exists( 'is_super_admin' ) && is_super_admin() ) || current_user_can( 'manage_options' ) || current_user_can( 'manage_daymark_subscriptions' ); }
	public static function design_tokens() {
		$defaults = array( 'ink' => '#172033', 'muted' => '#6b7280', 'surface' => '#ffffff', 'success' => '#11665e', 'warning' => '#9a5b00', 'danger' => '#9d3329', 'font' => 'system', 'radius' => 6, 'button' => 'solid' );
		$tokens = get_option( self::DESIGN_TOKENS_OPTION, array() );
		$tokens = is_array( $tokens ) ? array_merge( $defaults, $tokens ) : $defaults;
		foreach ( array( 'ink', 'muted', 'surface', 'success', 'warning', 'danger' ) as $key ) $tokens[ $key ] = sanitize_hex_color( $tokens[ $key ] ) ?: $defaults[ $key ];
		$tokens['font'] = in_array( $tokens['font'], array( 'system', 'serif', 'mono' ), true ) ? $tokens['font'] : $defaults['font'];
		$tokens['radius'] = in_array( absint( $tokens['radius'] ), array( 4, 6, 10 ), true ) ? absint( $tokens['radius'] ) : $defaults['radius'];
		$tokens['button'] = in_array( $tokens['button'], array( 'solid', 'outline' ), true ) ? $tokens['button'] : $defaults['button'];
		return $tokens;
	}

