	public function save_branding() {
		if ( ! self::can_manage() ) wp_die( esc_html__( 'You are not allowed to do this.', 'daymark-subscriptions' ) );
		check_admin_referer( 'daymark_save_branding' );
		$color = sanitize_hex_color( wp_unslash( $_POST['brand_color'] ?? '' ) ); $width = absint( $_POST['content_width'] ?? self::content_width() ); $width = in_array( $width, array( 960, 1200, 1320 ), true ) ? $width : self::content_width();
		$color = $color ?: self::brand_color();
		$tokens = self::design_tokens();
		if ( isset( $_POST['remove_logo'] ) ) delete_option( self::LOGO_ID_OPTION );
		if ( ! empty( $_FILES['daymark_logo']['name'] ) && UPLOAD_ERR_OK === (int) ( $_FILES['daymark_logo']['error'] ?? UPLOAD_ERR_NO_FILE ) ) { require_once ABSPATH . 'wp-admin/includes/file.php'; require_once ABSPATH . 'wp-admin/includes/media.php'; require_once ABSPATH . 'wp-admin/includes/image.php'; $logo_id = media_handle_upload( 'daymark_logo', 0 ); if ( ! is_wp_error( $logo_id ) ) update_option( self::LOGO_ID_OPTION, absint( $logo_id ), false ); }
		foreach ( array( 'ink', 'muted', 'surface', 'success', 'warning', 'danger' ) as $key ) if ( isset( $_POST['design_' . $key] ) ) $tokens[ $key ] = sanitize_hex_color( wp_unslash( $_POST['design_' . $key] ) ) ?: $tokens[ $key ];
		if ( isset( $_POST['design_font'] ) ) $tokens['font'] = in_array( sanitize_key( wp_unslash( $_POST['design_font'] ) ), array( 'system', 'serif', 'mono' ), true ) ? sanitize_key( wp_unslash( $_POST['design_font'] ) ) : $tokens['font'];
		if ( isset( $_POST['design_radius'] ) && in_array( absint( $_POST['design_radius'] ), array( 4, 6, 10 ), true ) ) $tokens['radius'] = absint( $_POST['design_radius'] );
		if ( isset( $_POST['design_button'] ) && in_array( sanitize_key( wp_unslash( $_POST['design_button'] ) ), array( 'solid', 'outline' ), true ) ) $tokens['button'] = sanitize_key( wp_unslash( $_POST['design_button'] ) );
		$color_saved = (bool) $color && ( update_option( self::BRAND_COLOR_OPTION, $color, false ) || self::brand_color() === $color ); $width_saved = update_option( self::CONTENT_WIDTH_OPTION, $width, false ) || self::content_width() === $width; $tokens_saved = update_option( self::DESIGN_TOKENS_OPTION, $tokens, false ) || self::design_tokens() === $tokens; $saved = $color_saved && $width_saved && $tokens_saved;
		wp_safe_redirect( admin_url( 'admin.php?page=daymark-subscriptions-design&daymark_branding_saved=' . ( $saved ? '1' : '0' ) ) ); exit;
	}

	public function create_plan() {
		if ( ! self::can_manage() ) wp_die( esc_html__( 'You are not allowed to do this.', 'daymark-subscriptions' ) );
		check_admin_referer( 'daymark_create_plan' );
		$name = sanitize_text_field( wp_unslash( $_POST['name'] ?? '' ) ); $slug = sanitize_title( $name ); $price = filter_var( wp_unslash( $_POST['price'] ?? '' ), FILTER_VALIDATE_FLOAT ); $intro_price = filter_var( wp_unslash( $_POST['intro_price'] ?? '' ), FILTER_VALIDATE_FLOAT ); $intro_price = false === $intro_price ? 0 : (float) $intro_price; $intro_cycles = min( 12, absint( $_POST['intro_cycles'] ?? 0 ) ); $currency = self::currency(); $interval_unit = sanitize_key( wp_unslash( $_POST['interval_unit'] ?? 'month' ) ); $trial_days = min( 365, absint( $_POST['trial_days'] ?? 0 ) ); $approval_mode = sanitize_key( wp_unslash( $_POST['approval_mode'] ?? 'direct' ) ); $sort_order = absint( $_POST['sort_order'] ?? 0 ); $featured = ! empty( $_POST['featured'] ) ? 1 : 0; $visibility = in_array( sanitize_key( wp_unslash( $_POST['catalog_visibility'] ?? 'visible' ) ), array( 'visible', 'hidden' ), true ) ? sanitize_key( wp_unslash( $_POST['catalog_visibility'] ?? 'visible' ) ) : 'visible'; $cta_label = sanitize_text_field( wp_unslash( $_POST['cta_label'] ?? '' ) ); $benefits = array_values( array_filter( array_map( 'trim', preg_split( '/\r?\n/', sanitize_textarea_field( wp_unslash( $_POST['benefits'] ?? '' ) ) ) ) ) ); $setup_fee = max( 0, (float) ( $_POST['setup_fee'] ?? 0 ) ); $minimum_commitment_cycles = min( 60, absint( $_POST['minimum_commitment_cycles'] ?? 0 ) ); $allow_promotion_codes = ! empty( $_POST['allow_promotion_codes'] ) ? 1 : 0; $quantity_enabled = ! empty( $_POST['quantity_enabled'] ) ? 1 : 0; $quantity_min = max( 1, min( 1000, absint( $_POST['quantity_min'] ?? 1 ) ) ); $quantity_max = max( $quantity_min, min( 1000, absint( $_POST['quantity_max'] ?? $quantity_min ) ) ); $tax_behavior = in_array( sanitize_key( wp_unslash( $_POST['tax_behavior'] ?? 'automatic' ) ), array( 'automatic', 'inclusive', 'exclusive' ), true ) ? sanitize_key( wp_unslash( $_POST['tax_behavior'] ?? 'automatic' ) ) : 'automatic';
		$slug = substr( $slug, 0, 80 ); $base_slug = $slug; $suffix = 2;
		while ( $slug && Daymark_Subscriptions_DB::get_plan_by_slug( $slug ) ) { $suffix_text = '-' . $suffix++; $slug = substr( $base_slug, 0, 80 - strlen( $suffix_text ) ) . $suffix_text; }
		$intro_valid = ! $intro_cycles || ( false !== $price && $intro_price >= 0 && $intro_price < (float) $price && in_array( $interval_unit, array( 'month', 'year' ), true ) );
		if ( ! $name || ! $slug || false === $price || $price < 0 || ! $intro_valid || ! preg_match( '/^[A-Z]{3}$/', $currency ) || ! in_array( $interval_unit, array( 'day', 'month', 'year' ), true ) || ! in_array( $approval_mode, array( 'direct', 'review' ), true ) ) wp_safe_redirect( add_query_arg( 'daymark_error', 'invalid', admin_url( 'admin.php?page=daymark-subscriptions-plans' ) ) );
