	public function process_privacy_request() {
		if ( ! self::can_manage() ) wp_die( esc_html__( 'You are not allowed to do this.', 'daymark-subscriptions' ) );
		check_admin_referer( 'daymark_process_privacy_request' );
		$user_id = absint( $_POST['user_id'] ?? 0 ); $decision = sanitize_key( wp_unslash( $_POST['decision'] ?? '' ) ); $requested = get_user_meta( $user_id, 'daymark_privacy_deletion_requested_at', true ); $user = get_userdata( $user_id ); $saved = false;
		if ( $user && $requested && in_array( $decision, array( 'approve', 'reject' ), true ) ) {
			if ( 'approve' === $decision ) {
				if ( user_can( $user_id, 'manage_options' ) ) {
					wp_safe_redirect( add_query_arg( array( 'page' => 'daymark-subscriptions-pending', 'daymark_privacy' => '0', 'daymark_privacy_error' => rawurlencode( __( 'Administrator profiles cannot be anonymized or deleted.', 'daymark-subscriptions' ) ) ), admin_url( 'admin.php' ) ) ); exit;
				}
				$saved = (bool) update_user_meta( $user_id, 'daymark_privacy_deletion_approved_at', current_time( 'mysql', true ) ); delete_user_meta( $user_id, 'daymark_privacy_deletion_requested_at' );
			} else { $saved = delete_user_meta( $user_id, 'daymark_privacy_deletion_requested_at' ); }
		}
		if ( $saved ) Daymark_Subscriptions_DB::record_audit_log( 'privacy_deletion_' . $decision, 'user', $user_id, array( 'billing_history_preserved' => true ) );
		wp_safe_redirect( admin_url( 'admin.php?page=daymark-subscriptions-pending&daymark_privacy=' . ( $saved ? '1' : '0' ) ) ); exit;
	}

