		$webhook_constant = 'live' === $mode ? 'DAYMARK_STRIPE_LIVE_WEBHOOK_SECRET' : 'DAYMARK_STRIPE_TEST_WEBHOOK_SECRET';
		if ( 'stripe' === Daymark_Payment_Provider::provider() && ! defined( $mode_constant ) && ( 'live' === $mode || ! defined( 'DAYMARK_STRIPE_SECRET_KEY' ) ) ) {
			$secret = trim( (string) wp_unslash( $_POST['stripe_secret_key'] ?? '' ) );
			if ( '' !== $secret ) update_option( 'daymark_stripe_' . $mode . '_secret_key', $secret, false );
		}
		if ( 'stripe' === Daymark_Payment_Provider::provider() && ! defined( $webhook_constant ) && ( 'live' === $mode || ! defined( 'DAYMARK_STRIPE_WEBHOOK_SECRET' ) ) ) {
			$webhook = trim( (string) wp_unslash( $_POST['stripe_webhook_secret'] ?? '' ) );
