riptions' ); ?></small><select name="approval_mode"><option value="direct"><?php echo esc_html__( 'Direct approval', 'daymark-subscriptions' ); ?></option><option value="review"><?php echo esc_html__( 'Admin review', 'daymark-subscriptions' ); ?></option></select></label><label><?php echo esc_html__( 'Sort order', 'daymark-subscriptions' ); ?><small><?php echo esc_html__( 'Lower numbers appear first', 'daymark-subscriptions' ); ?></small><input name="sort_order" type="number" min="0" step="1" value="0"></label><label class="daymark-check-field"><input name="featured" type="checkbox" value="1"> <span><?php echo esc_html__( 'Featured plan', 'daymark-subscriptions' ); ?><small><?php echo esc_html__( 'Highlight this offer on the public plans page.', 'daymark-subscriptions' ); ?></small></span></label><label class="daymark-form-wide"><?php echo esc_html__( 'Description', 'daymark-subscriptions' ); ?><small><?php echo esc_html__( 'Explain the value in a few clear sentences', 'daymark-subscriptions' ); ?></small><textarea name="description" class="large-text" placeholder="What does this membership include?"></textarea></label><label class="daymark-form-wide"><?php echo esc_html__( 'Benefits', 'daymark-subscriptions' ); ?><small><?php echo esc_html__( 'One customer-facing benefit per line, up to eight.', 'daymark-subscriptions' ); ?></small><textarea name="benefits" class="large-text" rows="5" placeholder="Unlimited projects&#10;Priority support"></textarea></label><div class="daymark-form-wide daymark-form-actions"><?php submit_button( __( 'Create plan', 'daymark-subscriptions' ), 'primary', 'submit', false ); ?></div></form></section>
