' ) ); ?></span></div><div class="daymark-plan-status"><span class="daymark-status <?php echo esc_attr( $plan['active'] ? 'is-active' : 'is-muted' ); ?>"><?php echo esc_html( $plan['active'] ? __( 'Active', 'daymark-subscriptions' ) : __( 'Inactive', 'daymark-subscriptions' ) ); ?></span><small><?php echo esc_html( $plan['active'] ? __( 'Visible to eligible customers', 'daymark-subscriptions' ) : __( 'Not available for checkout', 'daymark-subscriptions' ) ); ?></small></div></article><?php endforeach; ?></div><?php else : ?><div class="daymark-empty-state"><span class="daymark-empty-mark" aria-hidden="true"></span><h3><?php echo esc_html__( 'Your catalog is ready for its first offer', 'daymark-subscriptions' ); ?></h3><p><?php echo esc_html__( 'Create a plan above to give customers a clear starting point for membership.', 'daymark-subscriptions' ); ?></p></div><?php endif; ?></section></div><?php
