	public function subscriptions_page() {
		if ( ! self::can_manage() ) return;
		$status = sanitize_key( wp_unslash( $_GET['status'] ?? '' ) ); $search = sanitize_text_field( wp_unslash( $_GET['s'] ?? '' ) ); $page = max( 1, absint( $_GET['paged'] ?? 1 ) ); $per_page = 50; $total = Daymark_Subscriptions_DB::get_admin_subscription_count( $status, $search ); $pages = max( 1, (int) ceil( $total / $per_page ) ); $page = min( $page, $pages );
		$this->admin_header( __( 'Subscriptions', 'daymark-subscriptions' ), __( 'Search and review member lifecycle state.', 'daymark-subscriptions' ) );
		$rows = Daymark_Subscriptions_DB::get_admin_subscriptions( $status, $search, $per_page, $page );
		if ( method_exists( $this, 'render_duplicate_notice' ) ) {
			$this->render_duplicate_notice();
		}
		?><div class="daymark-panel"><form class="daymark-toolbar" method="get"><input type="hidden" name="page" value="daymark-subscriptions-list"><label class="screen-reader-text" for="daymark-subscription-search"><?php echo esc_html__( 'Search subscriptions', 'daymark-subscriptions' ); ?></label><input id="daymark-subscription-search" name="s" value="<?php echo esc_attr( $search ); ?>" placeholder="<?php echo esc_attr__( 'Search member, email, plan, or provider ID', 'daymark-subscriptions' ); ?>"><select name="status"><option value=""><?php echo esc_html__( 'All statuses', 'daymark-subscriptions' ); ?></option><?php foreach ( array( 'pending_review', 'payment_pending', 'pending_activation', 'recovery_required', 'active', 'past_due', 'paused', 'canceled', 'expired' ) as $option ) : ?><option value="<?php echo esc_attr( $option ); ?>" <?php selected( $status, $option ); ?>><?php echo esc_html( ucfirst( str_replace( '_', ' ', $option ) ) ); ?></option><?php endforeach; ?></select><?php submit_button( __( 'Filter', 'daymark-subscriptions' ), 'secondary', 'submit', false ); ?></form><?php $this->render_subscription_table( $rows, true ); ?></div></div><?php
		if ( $pages > 1 ) : ?><nav class="tablenav daymark-pagination" aria-label="<?php echo esc_attr__( 'Subscription pages', 'daymark-subscriptions' ); ?>"><div class="tablenav-pages"><?php echo wp_kses_post( paginate_links( array( 'base' => add_query_arg( 'paged', '%#%' ), 'format' => '', 'current' => $page, 'total' => $pages, 'add_args' => array_filter( array( 'page' => 'daymark-subscriptions-list', 's' => $search, 'status' => $status ) ) ) ) ); ?></div></nav><?php endif; ?><?php
	}

	private function render_duplicate_notice() {
		$duplicates = array();
		$duplicate_rows = Daymark_Subscriptions_DB::get_duplicate_subscription_users();
		if ( is_array( $duplicate_rows ) ) $duplicates = $duplicate_rows;
		if ( ! $duplicates ) return;
		?><section class="daymark-panel daymark-duplicate-notice"><div class="daymark-panel-heading"><div><span class="daymark-kicker"><?php echo esc_html__( 'Needs review', 'daymark-subscriptions' ); ?></span><h2><?php echo esc_html__( 'Duplicate subscription records', 'daymark-subscriptions' ); ?></h2><p><?php echo esc_html__( 'Review these members before changing access or billing. Use the subscription table bulk controls to revoke only the duplicate record; history is never deleted automatically.', 'daymark-subscriptions' ); ?></p></div><strong><?php echo esc_html( number_format_i18n( count( $duplicates ) ) ); ?></strong></div><ul class="daymark-duplicate-list"><?php foreach ( $duplicates as $duplicate ) : ?><li><span><strong><?php echo esc_html( $duplicate['display_name'] ?: __( 'Unknown member', 'daymark-subscriptions' ) ); ?></strong><small><?php echo esc_html( $duplicate['user_email'] . ' · ' . $duplicate['subscription_count'] . ' current records' ); ?></small></span><a class="button" href="<?php echo esc_url( add_query_arg( array( 'page' => 'daymark-subscriptions-list', 's' => $duplicate['user_email'] ), admin_url( 'admin.php' ) ) ); ?>"><?php echo esc_html__( 'Review records', 'daymark-subscriptions' ); ?></a></li><?php endforeach; ?></ul></section><?php
	}

	public function pending_page() {
		if ( ! self::can_manage() ) return;
		$this->admin_header( __( 'Pending approvals', 'daymark-subscriptions' ), __( 'Review subscription requests before payment and access begin.', 'daymark-subscriptions' ) );
		?><div class="daymark-panel"><p class="daymark-muted"><?php echo esc_html__( 'No payment is collected while a request is waiting here. Approving a request sends the member a secure payment link.', 'daymark-subscriptions' ); ?></p><?php $this->render_subscription_table( Daymark_Subscriptions_DB::get_admin_subscriptions( 'pending_review', '', 100 ), true ); ?></div><?php $this->render_privacy_requests(); ?></div><?php
	}

	private function render_privacy_requests() {
		$requests = get_users( array( 'meta_key' => 'daymark_privacy_deletion_requested_at', 'orderby' => 'registered', 'order' => 'ASC' ) );
		?><section class="daymark-panel"><div class="daymark-panel-heading"><div><span class="daymark-kicker"><?php echo esc_html__( 'Privacy operations', 'daymark-subscriptions' ); ?></span><h2><?php echo esc_html__( 'Account deletion requests', 'daymark-subscriptions' ); ?></h2><p><?php echo esc_html__( 'Approve only after confirming billing-retention requirements. Approval anonymizes profile data and preserves subscription/invoice history. Administrator profiles are protected and remain visible for review.', 'daymark-subscriptions' ); ?></p></div></div><table class="widefat striped daymark-table"><thead><tr><th><?php echo esc_html__( 'Member', 'daymark-subscriptions' ); ?></th><th><?php echo esc_html__( 'Requested', 'daymark-subscriptions' ); ?></th><th><?php echo esc_html__( 'Action', 'daymark-subscriptions' ); ?></th></tr></thead><tbody><?php foreach ( $requests as $user ) : $is_admin = user_can( $user->ID, 'manage_options' ); ?><tr><td><?php echo esc_html( $user->display_name ?: __( 'Unknown member', 'daymark-subscriptions' ) ); ?><br><span class="daymark-muted"><?php echo esc_html( $user->user_email ); ?></span><?php if ( $is_admin ) : ?><br><span class="daymark-status daymark-status-past_due"><?php echo esc_html__( 'Administrator · protected', 'daymark-subscriptions' ); ?></span><?php endif; ?></td><td><?php echo esc_html( get_user_meta( $user->ID, 'daymark_privacy_deletion_requested_at', true ) ); ?></td><td><?php if ( $is_admin ) : ?><p class="daymark-muted"><?php echo esc_html__( 'Administrator profiles cannot be anonymized or deleted.', 'daymark-subscriptions' ); ?></p><?php else : ?><form method="post" class="daymark-inline-review"><input type="hidden" name="action" value="daymark_process_privacy_request"><input type="hidden" name="user_id" value="<?php echo esc_attr( $user->ID ); ?>"><input type="hidden" name="decision" value="approve"><?php wp_nonce_field( 'daymark_process_privacy_request' ); ?><button class="button button-primary" type="submit"><?php echo esc_html__( 'Anonymize profile', 'daymark-subscriptions' ); ?></button></form><?php endif; ?><form method="post" class="daymark-inline-review"><input type="hidden" name="action" value="daymark_process_privacy_request"><input type="hidden" name="user_id" value="<?php echo esc_attr( $user->ID ); ?>"><input type="hidden" name="decision" value="reject"><?php wp_nonce_field( 'daymark_process_privacy_request' ); ?><button class="button" type="submit"><?php echo esc_html__( 'Reject', 'daymark-subscriptions' ); ?></button></form></td></tr><?php endforeach; if ( ! $requests ) : ?><tr><td colspan="3"><?php echo esc_html__( 'No account deletion requests are waiting for review.', 'daymark-subscriptions' ); ?></td></tr><?php endif; ?></tbody></table></section><?php
	}

	public function audit_page() {
		if ( ! self::can_manage() ) return;
		$this->admin_header( __( 'Audit log', 'daymark-subscriptions' ), __( 'Review administrator actions affecting subscription state.', 'daymark-subscriptions' ) );
		$this->render_job_monitor();
		$this->render_operation_monitor();
		$audit_page = max( 1, absint( $_GET['audit_page'] ?? 1 ) ); $audit_per_page = 10; $audit_pages = max( 1, (int) ceil( Daymark_Subscriptions_DB::get_audit_log_count() / $audit_per_page ) ); $audit_page = min( $audit_page, $audit_pages );
		$rows = Daymark_Subscriptions_DB::get_audit_logs( $audit_per_page, $audit_page ); $events = Daymark_Subscriptions_DB::get_stripe_events();
