them.', 'daymark-subscriptions' ); ?></p></div></div><table class="widefat striped daymark-table"><thead><tr><th><?php echo esc_html__( 'Received', 'daymark-subscriptions' ); ?></th><th><?php echo esc_html__( 'Event', 'daymark-subscriptions' ); ?></th><th><?php echo esc_html__( 'Status', 'daymark-subscriptions' ); ?></th><th><?php echo esc_html__( 'Action', 'daymark-subscriptions' ); ?></th></tr></thead><tbody><?php foreach ( $events as $event ) : ?><tr><td><?php echo esc_html( $event['received_at'] ); ?></td><td><code><?php echo esc_html( $event['event_type'] ); ?></code><br><span class="daymark-muted"><?php echo esc_html( $event['event_id'] ); ?></span></td><td><?php echo esc_html( ucfirst( $event['status'] ) ); ?></td><td><?php if ( 'processed' !== $event['status'] ) : ?><form method="post"><input type="hidden" name="action" value="daymark_replay_stripe_event"><input type="hidden" name="event_id" value="<?php echo esc_attr( $event['event_id'] ); ?>"><?php wp_nonce_field( 'daymark_replay_stripe_event' ); ?><button class="button" type="submit"><?php echo esc_html__( 'Replay', 'daymark-subscriptions' ); ?></button></form><?php else : ?>—<?php endif; ?></td></tr><?php endforeach; if ( ! $events ) : ?><tr><td colspan="4"><?php echo esc_html__( 'No Stripe webhook events have been received yet.', 'daymark-subscriptions' ); ?></td></tr><?php endif; ?></tbody></table></div></div><?php
