		$operations = Daymark_Subscriptions_DB::get_operations( 'awaiting_second_approval', 50 );
		?><section class="daymark-panel"><div class="daymark-panel-heading"><div><span class="daymark-kicker"><?php echo esc_html__( 'Second-admin review', 'daymark-subscriptions' ); ?></span><h2><?php echo esc_html__( 'Sensitive actions waiting for approval', 'daymark-subscriptions' ); ?></h2><p><?php echo esc_html__( 'A different administrator must approve these review, revoke, or billing actions before they execute.', 'daymark-subscriptions' ); ?></p></div></div><table class="widefat striped daymark-table"><thead><tr><th><?php echo esc_html__( 'Updated', 'daymark-subscriptions' ); ?></th><th><?php echo esc_html__( 'Action', 'daymark-subscriptions' ); ?></th><th><?php echo esc_html__( 'Subscription', 'daymark-subscriptions' ); ?></th><th><?php echo esc_html__( 'Requested by', 'daymark-subscriptions' ); ?></th><th><?php echo esc_html__( 'Approval', 'daymark-subscriptions' ); ?></th></tr></thead><tbody><?php foreach ( $operations as $operation ) : $payload = json_decode( (string) $operation['request_payload'], true ); $requested_by = absint( $payload['requested_by'] ?? 0 ); $requester = $requested_by ? get_userdata( $requested_by ) : false; ?><tr><td><?php echo esc_html( $operation['updated_at'] ); ?></td><td><code><?php echo esc_html( $operation['action'] ); ?></code></td><td>#<?php echo esc_html( $operation['subscription_id'] ); ?></td><td><?php echo esc_html( $requester ? $requester->display_name : __( 'Unknown administrator', 'daymark-subscriptions' ) ); ?></td><td><form method="post"><input type="hidden" name="action" value="daymark_approve_operation"><input type="hidden" name="operation_id" value="<?php echo esc_attr( $operation['id'] ); ?>"><?php wp_nonce_field( 'daymark_approve_operation' ); ?><button class="button button-primary" type="submit"><?php echo esc_html__( 'Approve action', 'daymark-subscriptions' ); ?></button></form></td></tr><?php endforeach; if ( ! $operations ) : ?><tr><td colspan="5"><?php echo esc_html__( 'No sensitive actions are waiting for a second administrator.', 'daymark-subscriptions' ); ?></td></tr><?php endif; ?></tbody></table></section><?php
	}

	public function approve_operation() {
		if ( ! self::can_manage() ) wp_die( esc_html__( 'You are not allowed to do this.', 'daymark-subscriptions' ) );
		check_admin_referer( 'daymark_approve_operation' );
		$id = absint( $_POST['operation_id'] ?? 0 ); $operation = Daymark_Subscriptions_DB::get_operation_by_id( $id );
		$payload = $operation ? json_decode( (string) $operation['request_payload'], true ) : array(); $payload = is_array( $payload ) ? $payload : array();
		if ( ! $operation || 'awaiting_second_approval' !== $operation['status'] || absint( $payload['requested_by'] ?? 0 ) === get_current_user_id() ) wp_die( esc_html__( 'This approval request is invalid or was created by the current administrator.', 'daymark-subscriptions' ) );
		$request = new WP_REST_Request( 'POST', '/daymark/v1/admin/operations/' . $id . '/approve' ); $request->set_param( 'id', $id ); $result = ( new Daymark_Subscriptions_REST() )->approve_operation( $request );
		if ( is_wp_error( $result ) ) wp_die( esc_html( $result->get_error_message() ) );
		wp_safe_redirect( admin_url( 'admin.php?page=daymark-subscriptions-audit' ) ); exit;
	}

	public function retry_operation() {
		if ( ! self::can_manage() ) wp_die( esc_html__( 'You are not allowed to do this.', 'daymark-subscriptions' ) );
		check_admin_referer( 'daymark_retry_operation' );
		$id = absint( $_POST['operation_id'] ?? 0 );
		$operation = false;
		foreach ( Daymark_Subscriptions_DB::get_operations( 'recovery_required', 200 ) as $row ) if ( (int) $row['id'] === $id ) { $operation = $row; break; }
		$subscription = $operation ? Daymark_Subscriptions_DB::get_subscription_by_id( $operation['subscription_id'] ) : false;
		$result = $subscription && 'stripe' === Daymark_Payment_Provider::provider() ? Daymark_Stripe::reconcile_subscription( $subscription['provider_subscription_id'] ) : false;
		if ( $operation ) Daymark_Subscriptions_DB::update_operation( $operation['id'], $result ? 'succeeded' : 'dead_letter', array( 'attempts' => (int) $operation['attempts'] + 1, 'last_error' => $result ? null : 'Provider reconciliation failed.', 'next_attempt_at' => null ) );
		wp_safe_redirect( admin_url( 'admin.php?page=daymark-subscriptions-audit' ) ); exit;
	}

	public function retry_job() {
		if ( ! self::can_manage() ) wp_die( esc_html__( 'You are not allowed to do this.', 'daymark-subscriptions' ) );
		check_admin_referer( 'daymark_retry_job' );
		Daymark_Subscriptions_DB::retry_job( sanitize_key( $_POST['job_key'] ?? '' ) );
		wp_safe_redirect( admin_url( 'admin.php?page=daymark-subscriptions-audit' ) ); exit;
	}

