		?><section class="daymark-panel daymark-plan-change-settings-card"><span class="daymark-kicker"><?php echo esc_html__( 'Data retention', 'daymark-subscriptions' ); ?></span><h2><?php echo esc_html__( 'Checkout and activation cleanup', 'daymark-subscriptions' ); ?></h2><p><?php echo esc_html__( 'Unclaimed guest accounts are retained long enough to recover payment or activate access. Billing records are never removed by this cleanup.', 'daymark-subscriptions' ); ?></p><ul class="daymark-retention-list"><li><?php echo esc_html__( 'Subscription and invoice history is preserved for financial records.', 'daymark-subscriptions' ); ?></li><li><?php echo esc_html__( 'Audit history is preserved for operational accountability.', 'daymark-subscriptions' ); ?></li><li><?php echo esc_html__( 'Approved privacy requests are scheduled for anonymization after the configured retention period.', 'daymark-subscriptions' ); ?></li><li><?php echo esc_html__( 'Expired, unclaimed activation records lose access but their financial history remains available.', 'daymark-subscriptions' ); ?></li></ul><form method="post" action="<?php echo esc_url( admin_url( 'admin-post.php' ) ); ?>" class="daymark-settings-form"><input type="hidden" name="action" value="daymark_save_policy"><?php wp_nonce_field( 'daymark_save_policy' ); ?><label class="daymark-inline-label" for="daymark-abandoned-retention-days"><?php echo esc_html__( 'Abandoned checkout retention', 'daymark-subscriptions' ); ?></label><input id="daymark-abandoned-retention-days" name="abandoned_retention_days" type="number" min="1" max="90" step="1" value="<?php echo esc_attr( self::abandoned_retention_days() ); ?>"><p class="description"><?php echo esc_html__( 'Allowed range: 1–90 days for incomplete or failed guest checkouts.', 'daymark-subscriptions' ); ?></p><label class="daymark-inline-label" for="daymark-pending-activation-retention-days"><?php echo esc_html__( 'Pending activation retention', 'daymark-subscriptions' ); ?></label><input id="daymark-pending-activation-retention-days" name="pending_activation_retention_days" type="number" min="1" max="90" step="1" value="<?php echo esc_attr( self::pending_activation_retention_days() ); ?>"><p class="description"><?php echo esc_html__( 'Allowed range: 1–90 days after verified payment. Unclaimed access expires after this period; billing and audit history stay intact.', 'daymark-subscriptions' ); ?></p><label class="daymark-inline-label" for="daymark-account-deletion-retention-days"><?php echo esc_html__( 'Approved deletion retention', 'daymark-subscriptions' ); ?></label><input id="daymark-account-deletion-retention-days" name="account_deletion_retention_days" type="number" min="1" max="365" step="1" value="<?php echo esc_attr( self::account_deletion_retention_days() ); ?>"><p class="description"><?php echo esc_html__( 'Approved requests are anonymized after this period. Financial and audit history remains preserved.', 'daymark-subscriptions' ); ?></p><?php submit_button( __( 'Save retention settings', 'daymark-subscriptions' ), 'primary' ); ?></form></section><?php
	}

