ss in production. Disabling this affects admin alerts only; member emails remain enabled.', 'daymark-subscriptions' ); ?></p><?php submit_button( __( 'Save notification settings', 'daymark-subscriptions' ), 'primary' ); ?></form></section><?php
	}

	private function render_notification_event_card() {
		$labels = array( 'subscription_created' => __( 'Subscription activated', 'daymark-subscriptions' ), 'pending_review' => __( 'Admin review request', 'daymark-subscriptions' ), 'approved_for_payment' => __( 'Review approval', 'daymark-subscriptions' ), 'subscription_cancelled' => __( 'Cancellation', 'daymark-subscriptions' ), 'subscription_paused' => __( 'Pause', 'daymark-subscriptions' ), 'subscription_resumed' => __( 'Resume', 'daymark-subscriptions' ), 'plan_changed' => __( 'Plan change', 'daymark-subscriptions' ), 'payment_updated' => __( 'Payment status', 'daymark-subscriptions' ), 'provider_cancelled' => __( 'Provider cancellation', 'daymark-subscriptions' ), 'renewal_due' => __( 'Renewal due', 'daymark-subscriptions' ), 'renewal_reminder' => __( 'Renewal reminder', 'daymark-subscriptions' ), 'trial_ending' => __( 'Trial ending', 'daymark-subscriptions' ), 'intro_expiring' => __( 'Introductory price ending', 'daymark-subscriptions' ), 'payment_recovery_required' => __( 'Payment recovery required', 'daymark-subscriptions' ), 'invoice_created' => __( 'Invoice created', 'daymark-subscriptions' ), 'invoice_paid' => __( 'Invoice paid', 'daymark-subscriptions' ), 'invoice_failed' => __( 'Invoice failed', 'daymark-subscriptions' ), 'subscription_expired' => __( 'Subscription expired', 'daymark-subscriptions' ) );
		$events = get_option( Daymark_Subscriptions_Mailer::EVENTS_OPTION, array() ); $events = is_array( $events ) ? array_merge( Daymark_Subscriptions_Mailer::event_defaults(), $events ) : Daymark_Subscriptions_Mailer::event_defaults(); $reply_to = get_option( Daymark_Subscriptions_Mailer::REPLY_TO_OPTION, '' );
		?><section class="daymark-panel daymark-plan-change-settings-card"><span class="daymark-kicker"><?php echo esc_html__( 'Notification policy', 'daymark-subscriptions' ); ?></span><h2><?php echo esc_html__( 'Event delivery controls', 'daymark-subscriptions' ); ?></h2><p><?php echo esc_html__( 'Keep transactional mail enabled by default, and disable only events your operating policy does not need.', 'daymark-subscriptions' ); ?></p><form method="post" action="<?php echo esc_url( admin_url( 'admin-post.php' ) ); ?>" class="daymark-settings-form"><input type="hidden" name="action" value="daymark_save_notifications"><?php wp_nonce_field( 'daymark_save_notifications' ); ?><label class="daymark-inline-label" for="daymark-notification-reply-to"><?php echo esc_html__( 'Reply-to email', 'daymark-subscriptions' ); ?></label><input id="daymark-notification-reply-to" name="notification_reply_to" type="email" value="<?php echo esc_attr( $reply_to ); ?>" placeholder="support@example.com"><fieldset class="daymark-notification-events"><legend><?php echo esc_html__( 'Enabled events', 'daymark-subscriptions' ); ?></legend><?php foreach ( $labels as $event => $label ) : ?><label class="daymark-check-field"><input type="checkbox" name="notification_events[<?php echo esc_attr( $event ); ?>]" value="1" <?php checked( ! empty( $events[ $event ] ) ); ?>><span><?php echo esc_html( $label ); ?></span></label><?php endforeach; ?></fieldset><?php submit_button( __( 'Save event controls', 'daymark-subscriptions' ), 'primary' ); ?></form></section><?php
	}

	private function render_notification_template_card() {
		$templates = get_option( Daymark_Subscriptions_Mailer::TEMPLATES_OPTION, array() ); $templates = is_array( $templates ) ? $templates : array(); $labels = Daymark_Subscriptions_Mailer::template_labels();
		$examples = Daymark_Subscriptions_Mailer::template_examples();
		?><section class="daymark-panel daymark-plan-change-settings-card"><span class="daymark-kicker"><?php echo esc_html__( 'Notification templates', 'daymark-subscriptions' ); ?></span><h2><?php echo esc_html__( 'Edit transactional copy', 'daymark-subscriptions' ); ?></h2><p><?php echo esc_html__( 'Edit the subject and HTML body for each transactional event. Leave a field blank to keep the built-in message.', 'daymark-subscriptions' ); ?></p><form method="post" action="<?php echo esc_url( admin_url( 'admin-post.php' ) ); ?>" class="daymark-settings-form"><input type="hidden" name="action" value="daymark_save_notifications"><?php wp_nonce_field( 'daymark_save_notifications' ); ?><?php foreach ( $labels as $event => $label ) : $template = is_array( $templates[ $event ] ?? null ) ? $templates[ $event ] : array(); $example = is_array( $examples[ $event ] ?? null ) ? $examples[ $event ] : array(); ?><fieldset class="daymark-notification-template"><legend><?php echo esc_html( $label ); ?></legend><label><?php echo esc_html__( 'Subject', 'daymark-subscriptions' ); ?><input type="text" name="notification_templates[<?php echo esc_attr( $event ); ?>][subject]" maxlength="160" value="<?php echo esc_attr( $template['subject'] ?? '' ); ?>" placeholder="<?php echo esc_attr( $example['subject'] ?? '' ); ?>"></label><label><?php echo esc_html__( 'HTML body', 'daymark-subscriptions' ); ?><textarea id="daymark-email-template-<?php echo esc_attr( $event ); ?>" class="daymark-code-editor" data-daymark-wysiwyg="1" name="notification_templates[<?php echo esc_attr( $event ); ?>][body]" rows="10" spellcheck="false" wrap="off" aria-label="<?php echo esc_attr( sprintf( __( '%s HTML email body', 'daymark-subscriptions' ), $label ) ); ?>"><?php echo esc_textarea( $template['body'] ?? '' ); ?></textarea><small><?php echo esc_html__( 'HTML is sanitized before saving. Use the supported placeholder tokens shown above.', 'daymark-subscriptions' ); ?></small></label><details class="daymark-template-example"><summary><?php echo esc_html__( 'Show built-in example', 'daymark-subscriptions' ); ?></summary><p><strong><?php echo esc_html__( 'Subject:', 'daymark-subscriptions' ); ?></strong> <?php echo esc_html( $example['subject'] ?? '' ); ?></p><pre><code><?php echo esc_html( $example['body'] ?? '' ); ?></code></pre></details></fieldset><?php endforeach; ?><?php submit_button( __( 'Save notification templates', 'daymark-subscriptions' ), 'primary' ); ?></form></section><?php
	}

	private function render_tax_settings_card() {
		if ( 'stripe' !== Daymark_Payment_Provider::provider() ) return;
		?><section class="daymark-panel daymark-plan-change-settings-card"><span class="daymark-kicker"><?php echo esc_html__( 'Tax', 'daymark-subscriptions' ); ?></span><h2><?php echo esc_html__( 'Stripe automatic tax', 'daymark-subscriptions' ); ?></h2><p><?php echo esc_html__( 'Let Stripe calculate tax during Checkout using the customer billing address and your Stripe Tax configuration.', 'daymark-subscriptions' ); ?></p><form method="post" action="<?php echo esc_url( admin_url( 'admin-post.php' ) ); ?>" class="daymark-settings-form"><input type="hidden" name="action" value="daymark_save_tax_settings"><?php wp_nonce_field( 'daymark_save_tax_settings' ); ?><label class="daymark-inline-label"><input type="checkbox" name="stripe_automatic_tax" value="1" <?php checked( get_option( Daymark_Stripe::AUTOMATIC_TAX_OPTION, false ) ); ?>> <?php echo esc_html__( 'Enable automatic tax for new Stripe Checkout sessions', 'daymark-subscriptions' ); ?></label><p class="description"><?php echo esc_html__( 'Existing subscriptions keep their provider configuration. Confirm your Stripe Tax registrations before enabling this option.', 'daymark-subscriptions' ); ?></p><?php submit_button( __( 'Save tax setting', 'daymark-subscriptions' ), 'primary' ); ?></form></section><?php
	}

	public function api_page() {
		if ( ! self::can_manage() ) return;
		$provider = Daymark_Payment_Provider::provider();
		$stripe_mode = Daymark_Stripe::mode();
		$stripe_configured = Daymark_Stripe::configured();
		$woocommerce_ready = ! empty( Daymark_Payment_Provider::woocommerce_capabilities()['ready'] );
		$this->admin_header( __( 'API Integration', 'daymark-subscriptions' ), __( 'Connect the selected payment provider without exposing credentials in the interface.', 'daymark-subscriptions' ) );
		$this->render_tax_settings_card();
		?><p class="daymark-provider-health-row"><button type="button" class="button" data-daymark-provider-health><?php echo esc_html__( 'Test connection', 'daymark-subscriptions' ); ?></button><span data-daymark-provider-health-status role="status" aria-live="polite"></span></p><div class="daymark-webhook-health" data-daymark-webhook-health><strong><?php echo esc_html__( 'Webhook health', 'daymark-subscriptions' ); ?></strong><span><?php echo esc_html__( 'Last received: not checked', 'daymark-subscriptions' ); ?></span><span><?php echo esc_html__( 'Last verified: not checked', 'daymark-subscriptions' ); ?></span><span><?php echo esc_html__( 'Last processed: not checked', 'daymark-subscriptions' ); ?></span><span><?php echo esc_html__( 'Last failure: not checked', 'daymark-subscriptions' ); ?></span></div><?php
		?><div class="daymark-settings-grid"><section class="daymark-panel"><div class="daymark-panel-heading"><div><span class="daymark-kicker"><?php echo esc_html__( 'Selected provider', 'daymark-subscriptions' ); ?></span><h2><?php echo esc_html( 'stripe' === $provider ? __( 'Stripe Checkout', 'daymark-subscriptions' ) : __( 'WooCommerce Checkout', 'daymark-subscriptions' ) ); ?></h2></div><span class="daymark-status <?php echo esc_attr( ( 'stripe' === $provider ? $stripe_configured : $woocommerce_ready ) ? 'is-active' : 'is-muted' ); ?>"><?php echo esc_html( ( 'stripe' === $provider ? $stripe_configured : $woocommerce_ready ) ? __( 'Ready', 'daymark-subscriptions' ) : __( 'Needs setup', 'daymark-subscriptions' ) ); ?></span></div><?php if ( 'stripe' === $provider ) : ?><p><?php echo esc_html__( 'Choose Sandbox for test payments or Live for real payments. Each mode keeps its own keys, webhook secret, and Stripe prices.', 'daymark-subscriptions' ); ?></p><form method="post" action="<?php echo esc_url( admin_url( 'admin-post.php' ) ); ?>" class="daymark-no-modal daymark-api-form"><input type="hidden" name="action" value="daymark_save_integration"><?php wp_nonce_field( 'daymark_save_integration' ); ?><label class="daymark-inline-label" for="daymark-stripe-mode"><?php echo esc_html__( 'Payment mode', 'daymark-subscriptions' ); ?></label><select id="daymark-stripe-mode" name="stripe_mode" <?php disabled( defined( 'DAYMARK_STRIPE_MODE' ) ); ?>><option value="test" <?php selected( $stripe_mode, 'test' ); ?>><?php echo esc_html__( 'Sandbox — test payments', 'daymark-subscriptions' ); ?></option><option value="live" <?php selected( $stripe_mode, 'live' ); ?>><?php echo esc_html__( 'Live — real payments', 'daymark-subscriptions' ); ?></option></select><p class="description"><?php echo esc_html__( 'Use Stripe test keys in Sandbox and live keys in Live. Keep the mode aligned with the webhook endpoint.', 'daymark-subscriptions' ); ?></p><label class="daymark-inline-label" for="daym