on></select><input type="number" min="0.01" step="0.01" placeholder="Amount" aria-label="<?php echo esc_attr__( 'Adjustment amount', 'daymark-subscriptions' ); ?>"><button type="button" class="button daymark-billing-action-button" data-daymark-billing-action><?php echo esc_html__( 'Apply', 'daymark-subscriptions' ); ?></button><span class="daymark-billing-action-status" role="status" aria-live="polite"></span></div></td><?php endif; ?><?php if ( $full ) : ?><td><?php if ( 'pending_review' === $row['status'] ) : ?><form method="post" class="daymark-inline-review"><input type="hidden" name="action" value="daymark_review_subscription"><input type="hidden" name="subscription_id" value="<?php echo esc_attr( $row['id'] ); ?>"><input type="hidden" name="decision" value="approve"><input type="hidden" name="return_page" value="<?php echo esc_attr( sanitize_key( $_GET['page'] ?? 'daymark-subscriptions-list' ) ); ?>"><label class="daymark-review-reason"><span><?php echo esc_html__( 'Reason', 'daymark-subscriptions' ); ?></span><input type="text" name="reason" maxlength="500" placeholder="<?php echo esc_attr__( 'Optional', 'daymark-subscriptions' ); ?>"></label><?php wp_nonce_field( 'daymark_review_subscription' ); ?><button class="button button-primary" type="submit"><?php echo esc_html__( 'Approve', 'daymark-subscriptions' ); ?></button></form><form method="post" class="daymark-inline-review"><input type="hidden" name="action" value="daymark_review_subscription"><input type="hidden" name="subscription_id" value="<?php echo esc_attr( $row['id'] ); ?>"><input type="hidden" name="decision" value="reject"><input type="hidden" name="return_page" value="<?php echo esc_attr( sanitize_key( $_GET['page'] ?? 'daymark-subscriptions-list' ) ); ?>"><label class="daymark-review-reason"><span><?php echo esc_html__( 'Reason', 'daymark-subscriptions' ); ?></span><input type="text" name="reason" maxlength="500" placeholder="<?php echo esc_attr__( 'Optional', 'daymark-subscriptions' ); ?>"></label><?php wp_nonce_field( 'daymark_review_subscription' ); ?><button class="button" type="submit"><?php echo esc_html__( 'Reject', 'daymark-subscriptions' ); ?></button></form><?php else : ?>—<?php endif; ?></td><?php endif; ?></tr><?php endforeach; if ( ! $rows ) : ?><tr><td colspan="<?php echo esc_attr( $full ? 7 : 4 ); ?>"><?php echo esc_html__( 'No subscriptions match this view. Adjust the filter or wait for the first subscription.', 'daymark-subscriptions' ); ?></td></tr><?php endif; ?></tbody></table><?php
	}

	private function render_notice() {
		$messages = array(
			'invalid' => array( 'error', __( 'The plan details are invalid.', 'daymark-subscriptions' ) ),
			'exists' => array( 'error', __( 'A plan with this slug already exists.', 'daymark-subscriptions' ) ),
		);
		foreach ( array( 'created', 'provider_saved', 'environment_saved', 'plan_change_saved', 'policy_saved', 'notifications_saved', 'integration_saved', 'branding_saved', 'review' ) as $key ) {
			if ( isset( $_GET[ 'daymark_' . $key ] ) ) $messages[ $key ] = '1' === sanitize_key( wp_unslash( $_GET[ 'daymark_' . $key ] ) ) ? array( 'success', __( 'Changes saved.', 'daymark-subscriptions' ) ) : array( 'error', __( 'Changes could not be saved.', 'daymark-subscriptions' ) );
		}
		$notice = $messages[ sanitize_key( wp_unslash( $_GET['daymark_error'] ?? '' ) ) ] ?? null;
		if ( ! $notice && ! empty( $_GET['daymark_review_error'] ) ) $notice = array( 'error', sanitize_text_field( rawurldecode( wp_unslash( $_GET['daymark_review_error'] ) ) ) );
		if ( ! $notice && ! empty( $_GET['daymark_privacy_error'] ) ) $notice = array( 'error', sanitize_text_field( rawurldecode( wp_unslash( $_GET['daymark_privacy_error'] ) ) ) );
		if ( ! $notice ) foreach ( array_reverse( array_keys( $messages ) ) as $key ) if ( isset( $_GET[ 'daymark_' . $key ] ) ) { $notice = $messages[ $key ]; break; }
		if ( $notice ) echo '<div class="notice notice-' . esc_attr( $notice[0] ) . ' is-dismissible"><p>' . esc_html( $notice[1] ) . '</p></div>';
	}
}
